// Create a pure TypeScript file with no imports
// This lesson will build typed tree node structures using only TypeScript

// Define your TreeNode interface here
interface TreeNode<T> {
  value: T;
  id?: number;
  children?: TreeNode<T>[];
}

// Create a typed tree node instance here
const rootNode: TreeNode<number> = {
  value: 10,
  id: 1,
  children: []
};

// Define a function to create tree nodes here
function createTreeNode<T>(value: T, id?: number): TreeNode<T> {
  return {
    value,
    id,
    children: []
  };
}

// Use createTreeNode to create child nodes and add them to rootNode's children array
const child1 = createTreeNode(20, 2);
const child2 = createTreeNode(30, 3);
rootNode.children = [child1, child2];

// Define a generic TreeNode interface here
// Already defined above as TreeNode<T>

// Create a generic tree node instance here
const stringNode: TreeNode<string> = {
  value: 'Hello',
  id: 4,
  children: []
};

// Define a recursive tree traversal function here
function traverseTree<T>(node: TreeNode<T>): T[] {
  const result: T[] = [node.value];
  if (node.children) {
    for (const child of node.children) {
      result.push(...traverseTree(child));
    }
  }
  return result;
}

